const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaFemale, FaMale, FaStethoscope, FaChurch, FaUserFriends, FaExclamationTriangle, FaChartLine } = require("react-icons/fa");
const { BiSupport, BiHide } = require("react-icons/bi");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function buildDeck() {
  let pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9'; 
  pres.title = 'The Global Burden of Mental Illness';

  const colors = {
    primary: "028090",    // Teal
    secondary: "00A896",  // Seafoam
    accent: "02C39A",     // Mint
    dark: "1E293B",       // Slate 800
    gray: "64748B",       // Slate 500
    lightGray: "F1F5F9",  // Slate 100
    bg: "F8FAFC",         // Slate 50
    white: "FFFFFF"
  };

  pres.defineSlideMaster({
    title: 'MASTER_SLIDE', 
    background: { color: colors.bg }
  });

  pres.defineSlideMaster({
    title: 'MASTER_DARK', 
    background: { color: colors.primary }
  });

  const iconFemale = await iconToBase64Png(FaFemale, `#${colors.white}`, 256);
  const iconMale = await iconToBase64Png(FaMale, `#${colors.white}`, 256);
  const iconMeds = await iconToBase64Png(FaStethoscope, `#${colors.primary}`, 256);
  const iconFaith = await iconToBase64Png(FaChurch, `#${colors.primary}`, 256);
  const iconFriends = await iconToBase64Png(FaUserFriends, `#${colors.primary}`, 256);
  const iconStigma = await iconToBase64Png(BiHide, `#${colors.white}`, 256);
  const iconAccess = await iconToBase64Png(FaExclamationTriangle, `#${colors.white}`, 256);
  const iconQuality = await iconToBase64Png(FaChartLine, `#${colors.white}`, 256);
  const iconSupport = await iconToBase64Png(BiSupport, `#${colors.white}`, 256);

  const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, color: "000000", opacity: 0.1 });

  // 1. Title Slide
  let slide1 = pres.addSlide({ masterName: "MASTER_DARK" });
  slide1.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 0.5, w: 9, h: 4.625, fill: { color: colors.primary }, line: { color: colors.accent, width: 2 } });

  slide1.addText("The Global Burden of\nMental Illness", {
    x: 1, y: 1.5, w: 8, h: 1.5, fontSize: 44, fontFace: "Georgia", 
    color: colors.white, bold: true, align: "left"
  });
  slide1.addText("Prevalence, Impact, and the Treatment Gap", {
    x: 1, y: 3.1, w: 8, h: 0.5, fontSize: 24, fontFace: "Calibri", 
    color: colors.accent, align: "left", italic: true
  });
  slide1.addText("Based on global data (2023) from Our World in Data / IHME", {
    x: 1, y: 4.0, w: 8, h: 0.5, fontSize: 14, fontFace: "Calibri", 
    color: "E2E8F0", align: "left"
  });

  // 2. Prevalence Slide
  let slide2 = pres.addSlide({ masterName: "MASTER_SLIDE" });
  slide2.addText("Hundreds of Millions Affected", {
    x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 32, fontFace: "Georgia", color: colors.dark, bold: true
  });

  slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.5, w: 4.25, h: 2.5, fill: { color: colors.white }, shadow: makeShadow() });
  slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.5, w: 4.25, h: 0.1, fill: { color: colors.primary } });
  slide2.addShape(pres.shapes.OVAL, { x: 2.15, y: 1.7, w: 0.9, h: 0.9, fill: { color: colors.primary } });
  slide2.addImage({ data: iconFemale, x: 2.2, y: 1.75, w: 0.8, h: 0.8 });

  slide2.addText("1 in 3", {
    x: 0.5, y: 2.7, w: 4.25, h: 0.6, fontSize: 48, fontFace: "Georgia", color: colors.dark, bold: true, align: "center"
  });
  slide2.addText("Women will experience major\ndepression in their lifetime", {
    x: 0.5, y: 3.3, w: 4.25, h: 0.6, fontSize: 16, fontFace: "Calibri", color: colors.gray, align: "center"
  });

  slide2.addShape(pres.shapes.RECTANGLE, { x: 5.25, y: 1.5, w: 4.25, h: 2.5, fill: { color: colors.white }, shadow: makeShadow() });
  slide2.addShape(pres.shapes.RECTANGLE, { x: 5.25, y: 1.5, w: 4.25, h: 0.1, fill: { color: colors.primary } });
  slide2.addShape(pres.shapes.OVAL, { x: 6.9, y: 1.7, w: 0.9, h: 0.9, fill: { color: colors.primary } });
  slide2.addImage({ data: iconMale, x: 6.95, y: 1.75, w: 0.8, h: 0.8 });

  slide2.addText("1 in 5", {
    x: 5.25, y: 2.7, w: 4.25, h: 0.6, fontSize: 48, fontFace: "Georgia", color: colors.dark, bold: true, align: "center"
  });
  slide2.addText("Men will experience major\ndepression in their lifetime", {
    x: 5.25, y: 3.3, w: 4.25, h: 0.6, fontSize: 16, fontFace: "Calibri", color: colors.gray, align: "center"
  });

  slide2.addText("Mental health conditions span from highly common (depression, anxiety) to less common but severe (schizophrenia, bipolar). A clear understanding of this scale is essential for effective policy planning.", {
    x: 0.5, y: 4.4, w: 9, h: 0.8, fontSize: 16, fontFace: "Calibri", color: colors.dark, align: "left"
  });

  // 3. Burden by Category
  let slide3 = pres.addSlide({ masterName: "MASTER_SLIDE" });
  slide3.addText("Disease Burden by Category (2023)", {
    x: 0.5, y: 0.4, w: 9, h: 0.6, fontSize: 32, fontFace: "Georgia", color: colors.dark, bold: true
  });
  slide3.addText("Disability-adjusted life years (DALYs) per 100,000 people", {
    x: 0.5, y: 1.0, w: 9, h: 0.3, fontSize: 16, fontFace: "Calibri", color: colors.gray, italic: true
  });

