const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaFemale, FaMale, FaStethoscope, FaChurch, FaUserFriends, FaExclamationTriangle, FaChartLine } = require("react-icons/fa");
const { BiSupport, BiHide } = require("react-icons/bi");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

async function buildDeck() {
  let pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9'; 
  pres.title = 'The Global Burden of Mental Illness';

  const colors = {
    primary: "028090",    // Teal
    secondary: "00A896",  // Seafoam
    accent: "02C39A",     // Mint
    dark: "1E293B",       // Slate 800
    gray: "64748B",       // Slate 500
    lightGray: "F1F5F9",  // Slate 100
    bg: "F8FAFC",         // Slate 50
    white: "FFFFFF"
  };

  pres.defineSlideMaster({
    title: 'MASTER_SLIDE', 
    background: { color: colors.bg }
  });

  pres.defineSlideMaster({
    title: 'MASTER_DARK', 
    background: { color: colors.primary }
  });

  const iconFemale = await iconToBase64Png(FaFemale, `#${colors.white}`, 256);
